import{_ as r,o as t,c as a,a3 as i}from"./chunks/framework.DBpCFmh2.js";const b=JSON.parse('{"title":"通信协议设计","description":"本文件面向扩展端（Chrome 扩展，Manifest V3）与 Agent 端（独立 Node.js 进程）之间的通信契约。","frontmatter":{"title":"通信协议设计","description":"本文件面向扩展端（Chrome 扩展，Manifest V3）与 Agent 端（独立 Node.js 进程）之间的通信契约。"},"headers":[],"relativePath":"系统架构设计/通信协议设计/index.md","filePath":"系统架构设计/通信协议设计/index.md","lastUpdated":null}'),l={name:"系统架构设计/通信协议设计/index.md"};function o(n,e,c,s,g,h){return t(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="通信协议设计" tabindex="-1">通信协议设计 <a class="header-anchor" href="#通信协议设计" aria-label="Permalink to &quot;通信协议设计&quot;">​</a></h1><details class="details custom-block"><summary>本文引用的源码文件</summary><p><strong>本文引用的文件</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js" target="_blank" rel="noreferrer">agent/src/server.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/local-agent-client.js" target="_blank" rel="noreferrer">src/background/local-agent-client.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/auth.js" target="_blank" rel="noreferrer">agent/src/auth.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js" target="_blank" rel="noreferrer">agent/src/security.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/executor.js" target="_blank" rel="noreferrer">agent/src/executor.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/client.js" target="_blank" rel="noreferrer">agent/src/mcp/client.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/registry.js" target="_blank" rel="noreferrer">agent/src/mcp/registry.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-executor.js" target="_blank" rel="noreferrer">src/background/tool-executor.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/agent-dispatcher.js" target="_blank" rel="noreferrer">src/background/agent-dispatcher.js</a></li></ul></details><h2 id="目录" tabindex="-1">目录 <a class="header-anchor" href="#目录" aria-label="Permalink to &quot;目录&quot;">​</a></h2><ol><li><a href="#引言">引言</a></li><li><a href="#项目结构与通信边界">项目结构与通信边界</a></li><li><a href="#核心组件与职责">核心组件与职责</a></li><li><a href="#架构总览">架构总览</a></li><li><a href="#详细协议规范">详细协议规范</a></li><li><a href="#认证与-token-交换流程">认证与 Token 交换流程</a></li><li><a href="#mcp-协议集成与工具发现">MCP 协议集成与工具发现</a></li><li><a href="#命令执行与-websocket-流式输出">命令执行与 WebSocket 流式输出</a></li><li><a href="#依赖关系分析">依赖关系分析</a></li><li><a href="#性能连接管理与重连策略">性能、连接管理与重连策略</a></li><li><a href="#错误处理与状态码约定">错误处理与状态码约定</a></li><li><a href="#版本兼容性与迁移指南">版本兼容性与迁移指南</a></li><li><a href="#故障排查清单">故障排查清单</a></li><li><a href="#结论">结论</a></li></ol><h2 id="引言" tabindex="-1">引言 <a class="header-anchor" href="#引言" aria-label="Permalink to &quot;引言&quot;">​</a></h2><p>本文件面向扩展端（Chrome 扩展，Manifest V3）与 Agent 端（独立 Node.js 进程）之间的通信契约。当前稳定版本为 2.3.1，两端版本号保持同步。扩展端通过本地 HTTP REST API 和 WebSocket 双通道调用 Agent 的文件系统、命令执行、长期记忆、RAG、Skill 与 MCP 工具能力；Agent 源码修改后必须重启进程，新接口才生效。</p><h2 id="项目结构与通信边界" tabindex="-1">项目结构与通信边界 <a class="header-anchor" href="#项目结构与通信边界" aria-label="Permalink to &quot;项目结构与通信边界&quot;">​</a></h2><ul><li>扩展端：<code>src/background/local-agent-client.js</code> 封装所有 HTTP/WebSocket 请求，负责配对、Token 管理、可达性缓存、超时控制、MCP/Skill/RAG 客户端封装。</li><li>Agent 端：<code>agent/src/server.js</code> 提供 HTTP Router 与 WebSocket Server，统一鉴权、安全校验、日志、国际化、MCP 注册表、Skill 注册表、RAG 路由转发。</li><li>安全层：<code>agent/src/security.js</code> 提供路径白名单、硬阻止目录、命令黑白名单与分级管控。</li><li>认证层：<code>agent/src/auth.js</code> 实现配对码轮换、一次性配对、Token 验证与活跃窗口。</li><li>执行层：<code>agent/src/executor.js</code> 负责命令子进程、超时策略、WebSocket 广播与完成回放。</li><li>MCP 层：<code>agent/src/mcp/client.js</code> 与 <code>agent/src/mcp/registry.js</code> 管理多传输 MCP Client 实例、工具发现与调用。</li></ul><pre class="mermaid">graph TB
Extension[&quot;扩展端&lt;br/&gt;background/local-agent-client.js&quot;] --&gt; HTTP[&quot;HTTP REST API&lt;br/&gt;server.js 路由&quot;]
Extension --&gt; WS[&quot;WebSocket 命令流&lt;br/&gt;server.js upgrade&quot;]
HTTP --&gt; Auth[&quot;认证模块&lt;br/&gt;auth.js&quot;]
HTTP --&gt; Security[&quot;安全模块&lt;br/&gt;security.js&quot;]
HTTP --&gt; Executor[&quot;命令执行器&lt;br/&gt;executor.js&quot;]
HTTP --&gt; MCPRegistry[&quot;MCP 注册表&lt;br/&gt;mcp/registry.js&quot;]
MCPRegistry --&gt; MCPClient[&quot;MCP 客户端&lt;br/&gt;mcp/client.js&quot;]
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/local-agent-client.js#L40-L93" target="_blank" rel="noreferrer">src/background/local-agent-client.js#L40-L93</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L416-L548" target="_blank" rel="noreferrer">agent/src/server.js#L416-L548</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/auth.js#L117-L179" target="_blank" rel="noreferrer">agent/src/auth.js#L117-L179</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L109-L229" target="_blank" rel="noreferrer">agent/src/security.js#L109-L229</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/executor.js#L198-L386" target="_blank" rel="noreferrer">agent/src/executor.js#L198-L386</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/registry.js#L26-L108" target="_blank" rel="noreferrer">agent/src/mcp/registry.js#L26-L108</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/client.js#L35-L127" target="_blank" rel="noreferrer">agent/src/mcp/client.js#L35-L127</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/local-agent-client.js#L40-L93" target="_blank" rel="noreferrer">src/background/local-agent-client.js#L40-L93</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L388-L548" target="_blank" rel="noreferrer">agent/src/server.js#L388-L548</a></li></ul><h2 id="核心组件与职责" tabindex="-1">核心组件与职责 <a class="header-anchor" href="#核心组件与职责" aria-label="Permalink to &quot;核心组件与职责&quot;">​</a></h2><ul><li>扩展端客户端：维护已配对代理列表、活跃代理 ID、可达性缓存；统一发送带 Bearer Token 的请求；封装文件、命令、MCP、Skill、RAG、审计日志、回收站等 API。</li><li>Agent 服务端：解析请求、按路径分发到文件系统、命令、MCP、Skill、RAG、Memory、配置管理等子系统；统一 JSON 响应格式；支持 CORS 仅放行 Chrome 扩展来源。</li><li>认证模块：生成 6 位配对码，支持失败锁定与成功后立即轮换；持久化 extensionId → token 映射；verifyToken 更新 lastAuthTime。</li><li>安全模块：路径规范化、硬阻止目录、realpath 防符号链接绕过、allowedPaths 前缀校验；命令分级 deny/confirm/allow。</li><li>执行模块：spawn shell 子进程，stdout/stderr 流式广播，超时受管模式与旧语义兼容，完成结果回放给延迟连接的 WebSocket 客户端。</li><li>MCP 模块：支持 stdio、SSE、Streamable HTTP、WebSocket 四种传输；自动 listTools；合并多服务器工具并注入扩展端工具列表。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/local-agent-client.js#L95-L212" target="_blank" rel="noreferrer">src/background/local-agent-client.js#L95-L212</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L416-L548" target="_blank" rel="noreferrer">agent/src/server.js#L416-L548</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/auth.js#L30-L179" target="_blank" rel="noreferrer">agent/src/auth.js#L30-L179</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L62-L229" target="_blank" rel="noreferrer">agent/src/security.js#L62-L229</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/executor.js#L198-L386" target="_blank" rel="noreferrer">agent/src/executor.js#L198-L386</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/client.js#L35-L127" target="_blank" rel="noreferrer">agent/src/mcp/client.js#L35-L127</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/registry.js#L26-L108" target="_blank" rel="noreferrer">agent/src/mcp/registry.js#L26-L108</a></li></ul><h2 id="架构总览" tabindex="-1">架构总览 <a class="header-anchor" href="#架构总览" aria-label="Permalink to &quot;架构总览&quot;">​</a></h2><p>扩展端通过 <code>local-agent-client.js</code> 发起请求；Agent 端由 <code>server.js</code> 统一鉴权与安全校验后分发给具体业务模块。命令执行使用 HTTP 返回 execId 与 wsUrl，随后通过 WebSocket 实时推送 stdout/stderr/exit/error。MCP 工具在 Agent 端自动发现，扩展端按需拉取并动态注册为 AI 工具。</p><pre class="mermaid">sequenceDiagram
participant UI as &quot;扩展界面&quot;
participant Client as &quot;扩展端客户端&lt;br/&gt;local-agent-client.js&quot;
participant Server as &quot;Agent 服务端&lt;br/&gt;server.js&quot;
participant Exec as &quot;命令执行器&lt;br/&gt;executor.js&quot;
participant WS as &quot;WebSocket 通道&quot;
UI-&gt;&gt;Client : &quot;提交任务或执行命令&quot;
Client-&gt;&gt;Server : &quot;POST /api/exec (Bearer Token)&quot;
Server-&gt;&gt;Exec : &quot;executeCommand(command, cwd, timeoutMs)&quot;
Exec--&gt;&gt;Server : &quot;返回 execId 与 wsUrl&quot;
Server--&gt;&gt;Client : &quot;{success : true, level : &#39;allow&#39;, execId, wsUrl}&quot;
Client-&gt;&gt;WS : &quot;连接 ws : //{host} : {port}/ws/exec/{execId}?token=...&quot;
WS--&gt;&gt;Client : &quot;stdout/stderr/exit/error 流式消息&quot;
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/local-agent-client.js#L600-L626" target="_blank" rel="noreferrer">src/background/local-agent-client.js#L600-L626</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1605-L1673" target="_blank" rel="noreferrer">agent/src/server.js#L1605-L1673</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/executor.js#L198-L386" target="_blank" rel="noreferrer">agent/src/executor.js#L198-L386</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L2089-L2153" target="_blank" rel="noreferrer">agent/src/server.js#L2089-L2153</a></li></ul><h2 id="详细协议规范" tabindex="-1">详细协议规范 <a class="header-anchor" href="#详细协议规范" aria-label="Permalink to &quot;详细协议规范&quot;">​</a></h2><h3 id="通用响应结构" tabindex="-1">通用响应结构 <a class="header-anchor" href="#通用响应结构" aria-label="Permalink to &quot;通用响应结构&quot;">​</a></h3><p>所有 HTTP 响应统一为 JSON，包含以下字段：</p><ul><li><code>success</code>: boolean，表示业务是否成功。</li><li><code>error</code>: string，失败时的用户可读错误信息（国际化）。</li><li><code>httpStatus</code>: number，扩展端附加的 HTTP 状态码，用于区分“Agent 离线”与“资源不存在”。</li><li>其他业务字段：如 <code>version</code>、<code>platform</code>、<code>execId</code>、<code>content</code>、<code>tools</code>、<code>servers</code> 等。</li></ul><p>示例（健康检查）：</p><ul><li>请求：<code>GET /api/status</code></li><li>响应：<code>{ success: true, version: &quot;2.3.1&quot;, running: true, platform: &quot;...&quot;, ... }</code></li></ul><p>示例（需认证的状态详情）：</p><ul><li>请求：<code>GET /api/status/detail</code>，Header：<code>Authorization: Bearer &lt;token&gt;</code></li><li>响应：<code>{ success: true, pairCodeTTL, workdir, allowedPaths, commandTimeout, fileMaxSize, uploadMaxSize, resourceUsage, ... }</code></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L487-L500" target="_blank" rel="noreferrer">agent/src/server.js#L487-L500</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L724-L749" target="_blank" rel="noreferrer">agent/src/server.js#L724-L749</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/local-agent-client.js#L393-L443" target="_blank" rel="noreferrer">src/background/local-agent-client.js#L393-L443</a></li></ul><h3 id="认证头与跨域" tabindex="-1">认证头与跨域 <a class="header-anchor" href="#认证头与跨域" aria-label="Permalink to &quot;认证头与跨域&quot;">​</a></h3><ul><li>认证方式：<code>Authorization: Bearer &lt;token&gt;</code>。</li><li>跨域限制：仅允许 <code>chrome-extension://</code> 来源；非浏览器客户端不受 CORS 限制。</li><li>预检请求：OPTIONS 返回允许的 Header 与方法。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L242-L266" target="_blank" rel="noreferrer">agent/src/server.js#L242-L266</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L444-L457" target="_blank" rel="noreferrer">agent/src/server.js#L444-L457</a></li></ul><h3 id="文件操作-api" tabindex="-1">文件操作 API <a class="header-anchor" href="#文件操作-api" aria-label="Permalink to &quot;文件操作 API&quot;">​</a></h3><ul><li><code>/api/fs/read</code>：读取文件，返回 content、size、path。</li><li><code>/api/fs/write</code>：写入文件，支持 utf-8 与 base64。</li><li><code>/api/fs/list</code>：列出目录条目。</li><li><code>/api/fs/stat</code>：获取文件详细信息。</li><li><code>/api/fs/delete</code>：移至回收站。</li><li><code>/api/fs/download</code>：单文件或目录打包 zip，返回 base64。</li><li><code>/api/fs/download-stream</code>：二进制流下载，避免 base64 膨胀。</li><li><code>/api/files/upload</code>：multipart/form-data 上传。</li><li><code>/api/fs/upload-stream</code>：raw binary 流式上传。</li></ul><p>路径安全：所有路径先经 <code>checkPath</code>，命中硬阻止或不在 allowedPaths 则返回 403。</p><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1036-L1220" target="_blank" rel="noreferrer">agent/src/server.js#L1036-L1220</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1267-L1385" target="_blank" rel="noreferrer">agent/src/server.js#L1267-L1385</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L751-L862" target="_blank" rel="noreferrer">agent/src/server.js#L751-L862</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L109-L229" target="_blank" rel="noreferrer">agent/src/security.js#L109-L229</a></li></ul><h3 id="命令执行-api" tabindex="-1">命令执行 API <a class="header-anchor" href="#命令执行-api" aria-label="Permalink to &quot;命令执行 API&quot;">​</a></h3><ul><li><code>/api/exec</code>：异步或同步执行命令。 <ul><li>异步：返回 <code>execId</code> 与 <code>wsUrl</code>。</li><li>同步：<code>wait=true</code>，返回完整 stdout/stderr。</li></ul></li><li><code>/api/exec/stop</code>：停止运行中的命令。</li><li><code>/api/exec/detach</code>：显式 daemon 化，豁免超时。</li></ul><p>命令安全：<code>checkCommand</code> 返回 <code>level=&#39;deny&#39;</code> 或 <code>&#39;confirm&#39;</code>；deny 不可绕过，confirm 可 force 跳过。</p><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1605-L1689" target="_blank" rel="noreferrer">agent/src/server.js#L1605-L1689</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L691-L758" target="_blank" rel="noreferrer">agent/src/security.js#L691-L758</a></li></ul><h3 id="mcp-管理-api" tabindex="-1">MCP 管理 API <a class="header-anchor" href="#mcp-管理-api" aria-label="Permalink to &quot;MCP 管理 API&quot;">​</a></h3><ul><li><code>/api/mcp/servers</code>：添加/删除 MCP Server。</li><li><code>/api/mcp/servers/connect</code>：连接指定 Server。</li><li><code>/api/mcp/servers/disconnect</code>：断开 Server。</li><li><code>/api/mcp/servers/toggle</code>：启用/禁用 Server。</li><li><code>/api/mcp/tools</code>：获取工具列表，可选 <code>serverId</code> 过滤。</li><li><code>/api/mcp/call</code>：调用工具，参数 <code>serverId</code>、<code>toolName</code>、<code>args</code>。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1845-L1923" target="_blank" rel="noreferrer">agent/src/server.js#L1845-L1923</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L2012-L2021" target="_blank" rel="noreferrer">agent/src/server.js#L2012-L2021</a></li></ul><h3 id="skill-api" tabindex="-1">Skill API <a class="header-anchor" href="#skill-api" aria-label="Permalink to &quot;Skill API&quot;">​</a></h3><ul><li><code>/api/skill/list</code>、<code>/api/skill/detail</code>、<code>/api/skill/run</code>、<code>/api/skill/import</code>、<code>/api/skill/delete</code>、<code>/api/skill/toggle</code>、<code>/api/skill/reload</code>。</li><li>Agent Skill Markdown：<code>/api/skill/save-markdown</code>、<code>/api/skill/markdown</code>、<code>/api/skill/resource</code>、<code>/api/skill/agent-prompts</code>、<code>/api/skill/agent-prompt</code>。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1727-L2002" target="_blank" rel="noreferrer">agent/src/server.js#L1727-L2002</a></li></ul><h3 id="rag-与-memory-api" tabindex="-1">RAG 与 Memory API <a class="header-anchor" href="#rag-与-memory-api" aria-label="Permalink to &quot;RAG 与 Memory API&quot;">​</a></h3><ul><li>RAG：<code>/api/rag/install</code>、<code>/api/rag/install/status</code>、<code>/api/rag/detect</code>、<code>/api/rag/collections</code>、<code>/api/rag/search</code>、<code>/api/rag/collections/{id}/ingest</code>。</li><li>Memory：<code>/api/memory/*</code> 由 memoryRouter 转发。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L2023-L2072" target="_blank" rel="noreferrer">agent/src/server.js#L2023-L2072</a></li></ul><h2 id="认证与-token-交换流程" tabindex="-1">认证与 Token 交换流程 <a class="header-anchor" href="#认证与-token-交换流程" aria-label="Permalink to &quot;认证与 Token 交换流程&quot;">​</a></h2><p>配对码机制防止未授权扩展绑定 Agent。配对成功后，扩展端保存 token，后续所有需认证请求携带 Bearer Token。</p><pre class="mermaid">sequenceDiagram
participant Ext as &quot;扩展端&quot;
participant Agent as &quot;Agent 端&quot;
participant Auth as &quot;认证模块&quot;
Ext-&gt;&gt;Agent : &quot;POST /api/pair {code, extensionId}&quot;
Agent-&gt;&gt;Auth : &quot;handlePairRequest(code, extensionId)&quot;
Auth--&gt;&gt;Agent : &quot;{success, token|error}&quot;
Agent--&gt;&gt;Ext : &quot;{success, token}&quot;
Ext-&gt;&gt;Agent : &quot;GET /api/status/detail (Authorization : Bearer token)&quot;
Agent-&gt;&gt;Auth : &quot;verifyToken(token)&quot;
Auth--&gt;&gt;Agent : &quot;extensionId&quot;
Agent--&gt;&gt;Ext : &quot;{success, detail}&quot;
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L474-L485" target="_blank" rel="noreferrer">agent/src/server.js#L474-L485</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/auth.js#L138-L179" target="_blank" rel="noreferrer">agent/src/auth.js#L138-L179</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/auth.js#L117-L127" target="_blank" rel="noreferrer">agent/src/auth.js#L117-L127</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L537-L548" target="_blank" rel="noreferrer">agent/src/server.js#L537-L548</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/auth.js#L30-L179" target="_blank" rel="noreferrer">agent/src/auth.js#L30-L179</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L474-L548" target="_blank" rel="noreferrer">agent/src/server.js#L474-L548</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/local-agent-client.js#L275-L330" target="_blank" rel="noreferrer">src/background/local-agent-client.js#L275-L330</a></li></ul><h2 id="mcp-协议集成与工具发现" tabindex="-1">MCP 协议集成与工具发现 <a class="header-anchor" href="#mcp-协议集成与工具发现" aria-label="Permalink to &quot;MCP 协议集成与工具发现&quot;">​</a></h2><p>Agent 端启动时加载启用的 MCP Server，建立连接并调用 <code>listTools</code>，将工具聚合为 <code>{serverId, serverName, name, description, inputSchema}</code>。扩展端通过 <code>/api/mcp/tools</code> 拉取工具列表，并动态注册为 AI 工具，ID 格式为 <code>mcp_{serverId}_{toolName}</code>。</p><pre class="mermaid">classDiagram
class McpClient {
+string serverId
+string serverName
+boolean connected
+array tools
+connect()
+callTool(toolName, args)
+disconnect()
+getStatus()
}
class Registry {
+initializeMcpRegistry()
+getMcpTools(serverId?)
+callMcpTool(serverId, toolName, args)
+connectMcpServer(serverId)
+disconnectMcpServer(serverId)
+toggleMcpServer(serverId, enabled)
}
Registry --&gt; McpClient : &quot;管理多个实例&quot;
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/client.js#L35-L184" target="_blank" rel="noreferrer">agent/src/mcp/client.js#L35-L184</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/registry.js#L26-L138" target="_blank" rel="noreferrer">agent/src/mcp/registry.js#L26-L138</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/client.js#L35-L184" target="_blank" rel="noreferrer">agent/src/mcp/client.js#L35-L184</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/mcp/registry.js#L26-L138" target="_blank" rel="noreferrer">agent/src/mcp/registry.js#L26-L138</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-executor.js#L547-L625" target="_blank" rel="noreferrer">src/background/tool-executor.js#L547-L625</a></li></ul><h2 id="命令执行与-websocket-流式输出" tabindex="-1">命令执行与 WebSocket 流式输出 <a class="header-anchor" href="#命令执行与-websocket-流式输出" aria-label="Permalink to &quot;命令执行与 WebSocket 流式输出&quot;">​</a></h2><p>命令执行采用 HTTP + WebSocket 双通道：</p><ul><li>HTTP 返回 <code>execId</code> 与 <code>wsUrl</code>。</li><li>WebSocket URL 为 <code>ws://{host}:{port}/ws/exec/{execId}</code>，认证通过 Authorization Header 或 query <code>?token=</code>。</li><li>服务端每 30 秒 ping 检测半开连接，两拍无 pong 则 terminate。</li><li>执行器广播 stdout/stderr/exit/error，支持完成回放。</li></ul><pre class="mermaid">flowchart TD
Start[&quot;HTTP POST /api/exec&quot;] --&gt; CheckSecurity[&quot;安全检查 checkCommand&quot;]
CheckSecurity --&gt; |deny| Deny[&quot;返回 403 deny&quot;]
CheckSecurity --&gt; |confirm| Confirm[&quot;返回 confirm 提示&quot;]
CheckSecurity --&gt; |allow| Spawn[&quot;spawn 子进程&quot;]
Spawn --&gt; ReturnWS[&quot;返回 execId 与 wsUrl&quot;]
ReturnWS --&gt; ConnectWS[&quot;客户端连接 WebSocket&quot;]
ConnectWS --&gt; Stream[&quot;stdout/stderr 流式推送&quot;]
Stream --&gt; Exit[&quot;exit/error 结束&quot;]
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1605-L1673" target="_blank" rel="noreferrer">agent/src/server.js#L1605-L1673</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L2089-L2153" target="_blank" rel="noreferrer">agent/src/server.js#L2089-L2153</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/executor.js#L198-L386" target="_blank" rel="noreferrer">agent/src/executor.js#L198-L386</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1605-L1689" target="_blank" rel="noreferrer">agent/src/server.js#L1605-L1689</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L2089-L2153" target="_blank" rel="noreferrer">agent/src/server.js#L2089-L2153</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/executor.js#L198-L450" target="_blank" rel="noreferrer">agent/src/executor.js#L198-L450</a></li></ul><h2 id="依赖关系分析" tabindex="-1">依赖关系分析 <a class="header-anchor" href="#依赖关系分析" aria-label="Permalink to &quot;依赖关系分析&quot;">​</a></h2><ul><li><code>server.js</code> 依赖 <code>auth.js</code>、<code>security.js</code>、<code>executor.js</code>、<code>mcp/registry.js</code>、<code>skill/registry.js</code>、<code>memory/routes.js</code>、<code>rag/detect.js</code>、<code>logger.js</code>、<code>i18n.js</code>。</li><li><code>local-agent-client.js</code> 依赖扩展端存储、i18n、secret 加密，对外暴露统一 API。</li><li><code>tool-executor.js</code> 从 Agent 拉取 MCP 工具并注入 RAW_TOOLS 与 TOOL_HANDLERS。</li><li><code>agent-dispatcher.js</code> 负责子 Agent 调度，使用派生 sessionId 隔离信令。</li></ul><pre class="mermaid">graph LR
Server[&quot;server.js&quot;] --&gt; Auth[&quot;auth.js&quot;]
Server --&gt; Security[&quot;security.js&quot;]
Server --&gt; Executor[&quot;executor.js&quot;]
Server --&gt; MCPReg[&quot;mcp/registry.js&quot;]
Server --&gt; SkillReg[&quot;skill/registry.js&quot;]
Server --&gt; MemoryRoute[&quot;memory/routes.js&quot;]
Server --&gt; RagDetect[&quot;rag/detect.js&quot;]
LocalClient[&quot;local-agent-client.js&quot;] --&gt; ToolExecutor[&quot;tool-executor.js&quot;]
ToolExecutor --&gt; MCPReg
Dispatcher[&quot;agent-dispatcher.js&quot;] --&gt; LocalClient
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L13-L56" target="_blank" rel="noreferrer">agent/src/server.js#L13-L56</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/local-agent-client.js#L1-L8" target="_blank" rel="noreferrer">src/background/local-agent-client.js#L1-L8</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-executor.js#L547-L625" target="_blank" rel="noreferrer">src/background/tool-executor.js#L547-L625</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/agent-dispatcher.js#L1-L11" target="_blank" rel="noreferrer">src/background/agent-dispatcher.js#L1-L11</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L13-L56" target="_blank" rel="noreferrer">agent/src/server.js#L13-L56</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/local-agent-client.js#L1-L8" target="_blank" rel="noreferrer">src/background/local-agent-client.js#L1-L8</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/tool-executor.js#L547-L625" target="_blank" rel="noreferrer">src/background/tool-executor.js#L547-L625</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/agent-dispatcher.js#L1-L11" target="_blank" rel="noreferrer">src/background/agent-dispatcher.js#L1-L11</a></li></ul><h2 id="性能、连接管理与重连策略" tabindex="-1">性能、连接管理与重连策略 <a class="header-anchor" href="#性能、连接管理与重连策略" aria-label="Permalink to &quot;性能、连接管理与重连策略&quot;">​</a></h2><ul><li>请求超时：<code>agentRequest</code> 默认 60s，<code>agentGet</code> 默认 30s；文件上传 60s；下载 120s；RAG 搜索 180s；RAG 导入 600s。</li><li>可达性缓存：按 agentId 缓存 null/true/false，已知不可达直接返回错误，避免阻塞等待超时。</li><li>WebSocket 心跳：服务端每 30 秒 ping，无 pong 则 terminate；客户端空闲超时由调用方统一管理，避免双重超时冲突。</li><li>命令超时：支持受管模式（timeoutMs 协商）与旧语义（commandTimeout），期内有输出可延长，静默即杀。</li><li>优雅关闭：shutdown 终止进程、关闭 MCP、断开 WebSocket、销毁活跃 socket，10s 强制退出。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/local-agent-client.js#L393-L443" target="_blank" rel="noreferrer">src/background/local-agent-client.js#L393-L443</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/local-agent-client.js#L516-L550" target="_blank" rel="noreferrer">src/background/local-agent-client.js#L516-L550</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/local-agent-client.js#L662-L728" target="_blank" rel="noreferrer">src/background/local-agent-client.js#L662-L728</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/executor.js#L198-L275" target="_blank" rel="noreferrer">agent/src/executor.js#L198-L275</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L2239-L2288" target="_blank" rel="noreferrer">agent/src/server.js#L2239-L2288</a></li></ul><h2 id="错误处理与状态码约定" tabindex="-1">错误处理与状态码约定 <a class="header-anchor" href="#错误处理与状态码约定" aria-label="Permalink to &quot;错误处理与状态码约定&quot;">​</a></h2><ul><li>400：请求参数无效、JSON 解析失败、文件大小超限、路径缺失。</li><li>401：缺少 Authorization Header。</li><li>403：Token 无效、路径被拒绝、命令 deny、CORS 来源不被允许。</li><li>404：API 路径不存在、文件/目录不存在。</li><li>409：操作进行中、目标已存在。</li><li>429：操作过于频繁（冷却期）。</li><li>500：内部异常、RAG 路由加载失败、下载失败。</li><li>503：RAG 依赖不可用。</li></ul><p>扩展端附加 <code>httpStatus</code> 字段，便于区分“Agent 离线/网络错误”与“业务 404”。</p><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L417-L425" target="_blank" rel="noreferrer">agent/src/server.js#L417-L425</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L537-L548" target="_blank" rel="noreferrer">agent/src/server.js#L537-L548</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1036-L1220" target="_blank" rel="noreferrer">agent/src/server.js#L1036-L1220</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L2051-L2075" target="_blank" rel="noreferrer">agent/src/server.js#L2051-L2075</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/local-agent-client.js#L431-L443" target="_blank" rel="noreferrer">src/background/local-agent-client.js#L431-L443</a></li></ul><h2 id="版本兼容性与迁移指南" tabindex="-1">版本兼容性与迁移指南 <a class="header-anchor" href="#版本兼容性与迁移指南" aria-label="Permalink to &quot;版本兼容性与迁移指南&quot;">​</a></h2><ul><li>版本号：扩展端与 Agent 端均为 2.3.1，通过 <code>/api/status</code> 与 <code>/api/status/detail</code> 暴露。</li><li>向后兼容： <ul><li>命令执行支持受管模式（timeoutMs）与旧语义（commandTimeout），保证新 Agent × 旧插件行为不变。</li><li>扩展端保留 legacy 存储格式迁移逻辑，自动升级到 pairedAgents 数组。</li><li>WebSocket 认证优先 Authorization Header，回退到 query token，兼容浏览器 WebSocket API 限制。</li></ul></li><li>迁移建议： <ul><li>升级 Agent 后必须重启进程，新接口才生效。</li><li>若使用远程 Agent，注意 wsUrl 中本地地址替换为配置的 hostname。</li><li>MCP 工具 ID 格式固定为 <code>mcp_{serverId}_{toolName}</code>，扩展端工具名变更需重新加载。</li></ul></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L487-L500" target="_blank" rel="noreferrer">agent/src/server.js#L487-L500</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L724-L749" target="_blank" rel="noreferrer">agent/src/server.js#L724-L749</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/executor.js#L198-L206" target="_blank" rel="noreferrer">agent/src/executor.js#L198-L206</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/local-agent-client.js#L150-L183" target="_blank" rel="noreferrer">src/background/local-agent-client.js#L150-L183</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L2108-L2117" target="_blank" rel="noreferrer">agent/src/server.js#L2108-L2117</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/src/background/local-agent-client.js#L674-L693" target="_blank" rel="noreferrer">src/background/local-agent-client.js#L674-L693</a></li></ul><h2 id="故障排查清单" tabindex="-1">故障排查清单 <a class="header-anchor" href="#故障排查清单" aria-label="Permalink to &quot;故障排查清单&quot;">​</a></h2><ul><li>无法连接 Agent：检查 <code>/api/status</code> 是否可达，确认扩展来源是否为 <code>chrome-extension://</code>。</li><li>认证失败：确认 <code>/api/pair</code> 成功后 token 已保存，后续请求携带 <code>Authorization: Bearer &lt;token&gt;</code>。</li><li>文件操作 403：检查路径是否在 allowedPaths 内，是否命中硬阻止目录。</li><li>命令执行被拒绝：查看 <code>checkCommand</code> 返回 level，deny 不可绕过，confirm 可 force。</li><li>WebSocket 断连：检查服务端心跳是否正常，客户端是否长时间无输出导致超时。</li><li>MCP 工具未显示：确认 MCP Server 已连接且 enabled，扩展端已调用 <code>/api/mcp/tools</code>。</li><li>RAG 不可用：调用 <code>/api/rag/detect</code> 探测依赖，必要时安装依赖并重启 Agent。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L487-L500" target="_blank" rel="noreferrer">agent/src/server.js#L487-L500</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L537-L548" target="_blank" rel="noreferrer">agent/src/server.js#L537-L548</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L109-L229" target="_blank" rel="noreferrer">agent/src/security.js#L109-L229</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L691-L758" target="_blank" rel="noreferrer">agent/src/security.js#L691-L758</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L2089-L2153" target="_blank" rel="noreferrer">agent/src/server.js#L2089-L2153</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L2023-L2072" target="_blank" rel="noreferrer">agent/src/server.js#L2023-L2072</a></li></ul><h2 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h2><p>扩展端与 Agent 端的通信协议以 HTTP REST API 为主、WebSocket 为辅，兼顾安全性、可扩展性与可观测性。认证通过配对码与 Bearer Token 实现，安全层提供路径与命令双重防护，MCP 协议标准化外部工具接入，命令执行支持流式输出与超时策略。文档明确了协议序列图、消息格式、错误码、连接管理与兼容性策略，可作为扩展端与 Agent 端开发、集成与排障的权威参考。</p>`,106)])])}const d=r(l,[["render",o]]);export{b as __pageData,d as default};
